namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6-12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

namespace CourseCatalog.Services;

using CourseCatalog.Models;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    Instructor? GetInstructor(int id);
    void SubmitEnrollment(EnrollmentRequest request);
}

namespace CourseCatalog.Services;

using CourseCatalog.Models;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and software systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Explore the language of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Understand the fundamental laws governing the universe." },
            new() { Id = 4, Code = "ENGL", Name = "English", Description = "Develop critical reading, writing, and literary analysis skills." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examine the events and ideas that shaped the modern world." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Associate Professor", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning with over 15 years of teaching experience." },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Professor", Email = "rmartinez@university.edu", Bio = "Dr. Martinez is a renowned mathematician whose research focuses on topology and abstract algebra." },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Assistant Professor", Email = "sjohnson@university.edu", Bio = "Dr. Johnson is a physicist researching quantum computing and its applications in modern technology." },
            new() { Id = 4, Name = "Prof. James Wright", Title = "Professor", Email = "jwright@university.edu", Bio = "Prof. Wright is an award-winning author and literary critic specializing in contemporary American fiction." },
            new() { Id = 5, Name = "Dr. Emily Park", Title = "Associate Professor", Email = "epark@university.edu", Bio = "Dr. Park is a historian focused on 20th-century global conflicts and diplomatic history." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, data structures, and algorithmic thinking.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of essential data structures including trees, graphs, and hash tables, along with algorithm design and analysis.", Credits = 4, Schedule = "TTh 1:00-2:15 PM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 301", Title = "Artificial Intelligence", Description = "Explore the principles and techniques of artificial intelligence including search, knowledge representation, and machine learning.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", Location = "Tech Building 110", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential and integral calculus of single-variable functions.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", Location = "Math Building 100", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and systems of linear equations.", Credits = 3, Schedule = "TTh 10:30-11:45 AM", Location = "Math Building 204", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Code = "MATH 301", Title = "Abstract Algebra", Description = "An introduction to algebraic structures including groups, rings, and fields.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", Location = "Math Building 310", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "TTh 9:00-10:15 AM", Location = "Physics Lab 101", DepartmentId = 3, InstructorId = 3 },
            new() { Id = 8, Code = "PHYS 201", Title = "Quantum Mechanics", Description = "Introduction to quantum theory, wave functions, and the Schrödinger equation.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", Location = "Physics Lab 220", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 9, Code = "ENGL 101", Title = "English Composition", Description = "Develop foundational skills in academic writing, argumentation, and critical analysis.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", Location = "Humanities 105", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "ENGL 205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "TTh 2:30-3:45 PM", Location = "Humanities 210", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 11, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times through the early modern period.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", Location = "Liberal Arts 300", DepartmentId = 5, InstructorId = 5 },
            new() { Id = 12, Code = "HIST 202", Title = "Modern World History", Description = "Examination of global events from the Industrial Revolution to the present.", Credits = 3, Schedule = "TTh 11:00 AM-12:15 PM", Location = "Liberal Arts 315", DepartmentId = 5, InstructorId = 5 },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return query.ToList().AsReadOnly();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

