@page "/"
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-5 bg-primary text-white rounded mb-4">
    <h1 class="display-4 fw-bold">University Course Catalog</h1>
    <p class="lead">Discover courses, explore departments, and enroll today.</p>
    <div class="mt-3">
        <a href="/courses" class="btn btn-light btn-lg me-2">Browse Courses</a>
        <a href="/enroll" class="btn btn-outline-light btn-lg">Enroll Now</a>
    </div>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
        @foreach (var course in featuredCourses)
        {
            var dept = CatalogService.GetDepartment(course.DepartmentId);
            <div class="col">
                <FeaturedCourseCard Course="course" DepartmentName="@(dept?.Name ?? "")" />
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <h2 class="mb-3">Browse by Department</h2>
    <div class="row row-cols-2 row-cols-md-3 row-cols-lg-5 g-3">
        @foreach (var dept in departments)
        {
            <div class="col">
                <DepartmentLink Department="dept" />
            </div>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = Array.Empty<Course>();
    private IReadOnlyList<Department> departments = Array.Empty<Department>();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

