@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="mb-4">
    <CourseFilters Departments="departments" Search="@Search" DepartmentId="@DepartmentId" />
</div>

<p class="text-muted">Showing @courses.Count course(s)</p>

@if (courses.Count == 0)
{
    <div class="alert alert-info">
        No courses found. Try adjusting your search or filter criteria.
    </div>
}
else
{
    @foreach (var course in courses)
    {
        var dept = CatalogService.GetDepartment(course.DepartmentId);
        <CourseCard Course="course" DepartmentName="@(dept?.Name ?? "")" />
    }
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Course> courses = Array.Empty<Course>();
    private IReadOnlyList<Department> departments = Array.Empty<Department>();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="/courses" class="btn btn-outline-secondary">Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="mb-4">
        <h1>@course.Code — @course.Title</h1>
        <p class="lead">@course.Description</p>
    </div>

    <div class="row mb-4">
        <div class="col-md-6">
            <table class="table">
                <tbody>
                    <tr>
                        <th scope="row">Credits</th>
                        <td>@course.Credits</td>
                    </tr>
                    <tr>
                        <th scope="row">Schedule</th>
                        <td>@course.Schedule</td>
                    </tr>
                    <tr>
                        <th scope="row">Location</th>
                        <td>@course.Location</td>
                    </tr>
                    <tr>
                        <th scope="row">Department</th>
                        <td>
                            @if (department is not null)
                            {
                                <a href="/courses?departmentId=@department.Id">@department.Name</a>
                            }
                        </td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>

    @if (instructor is not null)
    {
        <h3 class="mb-3">Instructor</h3>
        <InstructorBio Instructor="instructor" />
    }

    <div class="mt-4">
        <a href="/enroll?courseId=@course.Id" class="btn btn-primary me-2">Enroll Now</a>
        <a href="/courses" class="btn btn-outline-secondary">Back to Courses</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll</PageTitle>

<h1 class="mb-4">Course Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@(selectedCourseName)</strong> has been received.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-primary ms-2">Submit Another</a>
    </div>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">— Select a course —</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private IReadOnlyList<Course> courses = Array.Empty<Course>();
    private bool submitted;
    private string selectedCourseName = "";

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollment(Model);
        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} — {course.Title}" : "the selected course";
        submitted = true;
    }
}

